func (q *Queries) LockGovernanceCaseIdentity(ctx context.Context, arg LockGovernanceCaseIdentityParams) error {
	_, err := q.db.Exec(ctx, lockGovernanceCaseIdentity,
		arg.WorkspaceID,
		arg.SubjectType,
		arg.SubjectID,
		arg.RuleID,
	)
	return err
}

